import { BookOpen } from 'lucide-react';
import { useState } from 'react';

import type { Article } from '../../types/common';
import { CardGridSkeleton } from '../common/CardSkeleton';
import ShowMoreButton from '../core/ShowMoreButton';

import ArticleGrid from './ArticleGrid';

interface ArticlesProps {
  initialArticles: Article[];
  selectedTags: string[];
  isLoading?: boolean;
}

export default function Articles({ initialArticles, selectedTags, isLoading }: ArticlesProps) {
  const [showAll, setShowAll] = useState(false);

  // Show all articles if filtering is active or showAll is true
  const displayedArticles =
    selectedTags.length > 0 || showAll ? initialArticles : initialArticles.slice(0, 3);

  return (
    <section
      id="articles"
      className="py-8 bg-gradient-to-b from-white to-gray-50 dark:from-gray-900 dark:to-neutral-darker scroll-mt-24"
    >
      <div className="container mx-auto px-6">
        <div className="flex items-center justify-between mb-6">
          <div className="flex items-center gap-3">
            <BookOpen className="w-8 h-8 text-primary dark:text-primary-light" />
            <h2 className="text-4xl font-bold text-neutral-dark dark:text-white">
              Featured Articles
            </h2>
          </div>
          {initialArticles.length > 3 && !selectedTags.length && (
            <ShowMoreButton showAll={showAll} onClick={() => setShowAll(!showAll)} />
          )}
        </div>

        {isLoading ? (
          <CardGridSkeleton />
        ) : displayedArticles.length > 0 ? (
          <ArticleGrid articles={displayedArticles} />
        ) : (
          <div className="min-h-[400px] flex items-center justify-center bg-white dark:bg-neutral-dark rounded-xl">
            <p className="text-neutral-dark/70 dark:text-white/70">
              No results found. Try a different tag, or clear the filters to see all featured
              articles.
            </p>
          </div>
        )}
      </div>
    </section>
  );
}
